import{_ as t,c as a,o as r,aj as n}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"Enrichment","description":"Learn how adding fat, sugar, eggs, and dairy affects dough texture, tenderness, and flavor in enriched breads.","frontmatter":{"title":"Enrichment","description":"Learn how adding fat, sugar, eggs, and dairy affects dough texture, tenderness, and flavor in enriched breads.","head":[["meta",{"name":"description","content":"Learn how adding fat, sugar, eggs, and dairy affects dough texture, tenderness, and flavor in enriched breads."}],["meta",{"property":"og:title","content":"Enrichment"}],["meta",{"property":"og:description","content":"Learn how adding fat, sugar, eggs, and dairy affects dough texture, tenderness, and flavor in enriched breads."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/enrichment.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Enrichment"}],["meta",{"name":"twitter:description","content":"Learn how adding fat, sugar, eggs, and dairy affects dough texture, tenderness, and flavor in enriched breads."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/enrichment.html"}]]},"headers":[],"relativePath":"guides/enrichment.md","filePath":"guides/enrichment.md"}'),i={name:"guides/enrichment.md"};function s(o,e,d,h,l,g){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="enriched-doughs" tabindex="-1">Enriched Doughs <a class="header-anchor" href="#enriched-doughs" aria-label="Permalink to “Enriched Doughs”">​</a></h1><p>Enriched doughs add ingredients like fats, sugar, eggs, and dairy to a lean formula. Those additions change both flavor and mechanics: usually softer crumb, richer taste, and different fermentation behavior.</p><h3 id="how-enrichment-ingredients-affect-dough" tabindex="-1">How Enrichment Ingredients Affect Dough <a class="header-anchor" href="#how-enrichment-ingredients-affect-dough" aria-label="Permalink to “How Enrichment Ingredients Affect Dough”">​</a></h3><ul><li><p><strong>Fats (oil, butter, shortening)</strong><br> Soften the crumb, improve tenderness, and slow staling. Higher-fat doughs stay soft longer and are easier to shape.</p></li><li><p><strong>Sugar</strong><br> Adds sweetness, boosts browning, and provides extra food for yeast. It also helps the crumb stay moist.</p></li><li><p><strong>Eggs</strong><br> Make the dough richer, add structure and color, and improve elasticity. Egg yolks contribute fat; egg whites add protein.</p></li><li><p><strong>Milk &amp; Dairy</strong><br> Add flavor, tenderness, and improved browning due to natural sugars and proteins. They also slightly tighten the crumb.</p></li></ul><p>These enrichments can be used lightly or heavily depending on the style of dough. A hoagie roll may use just a touch of oil and sugar, while a brioche or certain pizza doughs can include much higher levels.</p><p><strong>Examples:</strong> hoagie rolls, sandwich loaves, brioche, enriched-style pizza doughs.</p><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/ingredients/flour.html">Flour</a></li><li><a href="/recipes/lightly-enriched-hoagie.html">Lightly Enriched Hoagie Rolls</a></li></ul>',8)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
